#!/usr/bin/env node
// Extract the loadable memory image of an ELF binary and print it as JSON:
// { "<address>": <32-bit little-endian word value>, ... }
'use strict';

const fs = require('fs');

function main() {
  const path = process.argv[2];
  if (!path) {
    process.stderr.write('usage: node extract.js <binary>\n');
    process.exit(1);
  }
  const buf = fs.readFileSync(path);

  if (buf.length < 64 || buf[0] !== 0x7f || buf[1] !== 0x45 || buf[2] !== 0x4c || buf[3] !== 0x46) {
    throw new Error('not an ELF file');
  }

  const is64 = buf[4] === 2;        // EI_CLASS
  const little = buf[5] !== 2;      // EI_DATA (2 == ELFDATA2MSB)

  const u16 = (o) => (little ? buf.readUInt16LE(o) : buf.readUInt16BE(o));
  const u32 = (o) => (little ? buf.readUInt32LE(o) : buf.readUInt32BE(o));
  const u64 = (o) => Number(little ? buf.readBigUInt64LE(o) : buf.readBigUInt64BE(o));
  const addr = (o) => (is64 ? u64(o) : u32(o));

  // ELF header offsets
  const e_phoff = is64 ? addr(0x20) : addr(0x1c);
  const e_phentsize = u16(is64 ? 0x36 : 0x2a);
  const e_phnum = u16(is64 ? 0x38 : 0x2c);

  const PT_LOAD = 1;

  // Byte-level memory image of everything backed by the file.
  const bytes = new Map();
  const segments = [];

  for (let i = 0; i < e_phnum; i++) {
    const o = e_phoff + i * e_phentsize;
    if (o + e_phentsize > buf.length) break;
    if (u32(o) !== PT_LOAD) continue;

    let p_offset, p_vaddr, p_filesz;
    if (is64) {
      p_offset = u64(o + 0x08);
      p_vaddr = u64(o + 0x10);
      p_filesz = u64(o + 0x20);
    } else {
      p_offset = u32(o + 0x04);
      p_vaddr = u32(o + 0x08);
      p_filesz = u32(o + 0x10);
    }
    if (p_filesz === 0) continue;
    const end = Math.min(p_offset + p_filesz, buf.length);
    const n = end - p_offset;
    if (n <= 0) continue;
    segments.push([p_vaddr, n]);
    for (let k = 0; k < n; k++) bytes.set(p_vaddr + k, buf[p_offset + k]);
  }

  // Emit naturally aligned 4-byte words that are fully backed by file contents.
  const out = {};
  const emitted = new Set();
  for (const [vaddr, n] of segments) {
    const start = vaddr + ((4 - (vaddr % 4)) % 4);
    for (let a = start; a + 3 < vaddr + n; a += 4) {
      if (emitted.has(a)) continue;
      const b0 = bytes.get(a), b1 = bytes.get(a + 1), b2 = bytes.get(a + 2), b3 = bytes.get(a + 3);
      if (b0 === undefined || b1 === undefined || b2 === undefined || b3 === undefined) continue;
      const value = little
        ? (b0 + b1 * 0x100 + b2 * 0x10000 + b3 * 0x1000000)
        : (b3 + b2 * 0x100 + b1 * 0x10000 + b0 * 0x1000000);
      // Skip words whose sign interpretation is ambiguous (>= 2^31).
      if (value >= 2147483648) continue;
      emitted.add(a);
      out[String(a)] = value;
    }
  }

  const keys = Object.keys(out).sort((x, y) => Number(x) - Number(y));
  const parts = keys.map((k) => JSON.stringify(k) + ':' + out[k]);
  process.stdout.write('{' + parts.join(',') + '}\n');
}

main();

